// ======================================================
// extract event_log JSON - versión robusta
// Hikvision / teclado -> Node-RED
// Acepta payload como string, Buffer u objeto multipart
// ======================================================

function asText(value) {
    if (value === null || value === undefined) return "";

    if (Buffer.isBuffer(value)) {
        return value.toString("utf8");
    }

    if (typeof value === "string") {
        return value;
    }

    if (typeof value === "object") {
        // Si viene como campo directo
        if (value.event_log) {
            if (Buffer.isBuffer(value.event_log)) return value.event_log.toString("utf8");
            if (typeof value.event_log === "string") return value.event_log;
            return JSON.stringify(value.event_log);
        }

        // Si viene como eventLog
        if (value.eventLog) {
            if (Buffer.isBuffer(value.eventLog)) return value.eventLog.toString("utf8");
            if (typeof value.eventLog === "string") return value.eventLog;
            return JSON.stringify(value.eventLog);
        }

        // Último recurso: convertir todo el objeto a texto
        return JSON.stringify(value);
    }

    return String(value);
}

// 1) Buscar texto en los lugares más comunes
let s = "";

// Caso normal
s = asText(msg.payload);

// Caso multipart procesado por HTTP In
if (!s || s === "{}") {
    if (msg.req && msg.req.body) {
        s = asText(msg.req.body);
    }
}

// Guardar una vista previa para debug
msg.preview = s.slice(0, 500);

// Si sigue vacío, avisar mejor
if (!s) {
    node.warn("No llegó contenido útil en payload ni req.body");
    msg.debug_payload_type = typeof msg.payload;
    msg.debug_payload = msg.payload;
    return msg;
}

// 2) Intentar parsear directo si ya es JSON
try {
    let direct = JSON.parse(s);

    // Puede venir como JSON completo
    if (direct.AccessControllerEvent) {
        msg.ev = direct;
        msg.acs = direct.AccessControllerEvent || {};
        msg.payload = msg.acs;
        return msg;
    }

    // Puede venir como objeto con event_log
    if (direct.event_log) {
        let ev2 = typeof direct.event_log === "string"
            ? JSON.parse(direct.event_log)
            : direct.event_log;

        msg.ev = ev2;
        msg.acs = ev2.AccessControllerEvent || {};
        msg.payload = msg.acs;
        return msg;
    }

} catch (e) {
    // No pasa nada, seguimos con búsqueda dentro del multipart
}

// 3) Buscar el campo multipart name="event_log"
let key = 'name="event_log"';
let i = s.indexOf(key);

// Algunas variantes pueden venir con comillas simples o distinto formato
if (i < 0) {
    key = "name='event_log'";
    i = s.indexOf(key);
}

if (i < 0) {
    // Si el texto entero contiene AccessControllerEvent, intentar extraer desde el primer {
    if (s.indexOf("AccessControllerEvent") >= 0) {
        let j0 = s.indexOf("{");
        let k0 = s.lastIndexOf("}");

        if (j0 >= 0 && k0 > j0) {
            let txt0 = s.slice(j0, k0 + 1).trim();

            try {
                msg.ev = JSON.parse(txt0);
                msg.acs = msg.ev.AccessControllerEvent || {};
                msg.payload = msg.acs;
                return msg;
            } catch (e) {
                node.warn("Encontré AccessControllerEvent pero no pude parsear JSON: " + e.message);
                msg.bad_json_head = txt0.slice(0, 300);
                return msg;
            }
        }
    }

    node.warn("No aparece name=\"event_log\" en body");
    msg.debug_payload_type = typeof msg.payload;
    msg.debug_payload_preview = s.slice(0, 500);
    return msg;
}

// 4) Buscar inicio del JSON después de event_log
let j = s.indexOf("{", i);
if (j < 0) {
    node.warn("No encuentro '{' luego de event_log");
    msg.debug_payload_preview = s.slice(i, i + 500);
    return msg;
}

// 5) Buscar final del JSON
let k = s.indexOf("\n--", j);
if (k < 0) k = s.indexOf("\r\n--", j);
if (k < 0) k = s.lastIndexOf("}") + 1;
if (k <= j) k = s.length;

let txt = s.slice(j, k).trim();

// 6) Parsear JSON final
try {
    msg.ev = JSON.parse(txt);
    msg.acs = msg.ev.AccessControllerEvent || {};
    msg.payload = msg.acs;

    node.status({
        fill: "green",
        shape: "dot",
        text: "event_log OK"
    });

    return msg;

} catch (e) {
    node.warn("JSON parse failed: " + e.message);
    msg.bad_json_head = txt.slice(0, 500);
    msg.debug_payload_preview = s.slice(0, 500);
    return msg;
}

// ======================================================
// CREAR REQUESTS DE CAMARAS - DINAMICO
// Lee access_control + cameras desde CONFIG central.
// ======================================================

const capture_id = msg.capture_id;

if (!capture_id) {
    node.error("No llegó capture_id", msg);
    return null;
}

const cfg = flow.get("hik_config") || {};
const TIMEOUT_MS = Number(cfg.capture_timeout_ms || 5000);

const devices = [];

// El teclado puede participar o no de la captura.
const ac = cfg.access_control || {};
if (ac.capture !== false && ac.ip) {
    devices.push({
        key: String(ac.key || "teclado"),
        label: String(ac.name || "Teclado"),
        ip: String(ac.ip),
        snapshot_path: String(ac.snapshot_path || "/ISAPI/Streaming/channels/1/picture")
    });
}

// Cámaras variables.
const cameras = Array.isArray(cfg.cameras) ? cfg.cameras : [];

for (const cam of cameras) {
    if (!cam || cam.capture === false || !cam.ip) continue;

    devices.push({
        key: String(cam.key || ("camara_" + (devices.length + 1))),
        label: String(cam.name || cam.key || "Cámara"),
        ip: String(cam.ip),
        snapshot_path: String(cam.snapshot_path || "/ISAPI/Streaming/channels/1/picture")
    });
}

if (!devices.length) {
    node.warn("No hay dispositivos configurados para captura");
}

// La lista esperada queda guardada por captura.
// El colector se adapta automáticamente a esta cantidad.
flow.set("capture_required_" + capture_id, devices.map(d => d.key));
flow.set("capture_imgs_" + capture_id, {});
flow.set("capture_failed_" + capture_id, {});

const msgs = devices.map(dev => {
    const m = RED.util.cloneMessage(msg);

    m.capture_id = capture_id;
    m.camera_key = dev.key;
    m.camera_label = dev.label;
    m.url = "http://" + dev.ip + dev.snapshot_path;
    m.payload = null;
    m.requestTimeout = TIMEOUT_MS;

    return m;
});

const timeoutMsg = RED.util.cloneMessage(msg);
timeoutMsg.capture_id = capture_id;
timeoutMsg.capture_timeout = true;
timeoutMsg.timeout_ms = TIMEOUT_MS;

setTimeout(() => {
    node.send([null, timeoutMsg]);
}, TIMEOUT_MS);

node.status({
    fill: "blue",
    shape: "dot",
    text:
        "pidiendo " + devices.length +
        " foto(s), timeout " + (TIMEOUT_MS / 1000) + "s"
});

return [msgs, null];

// Normaliza la respuesta de cada cámara Hikvision.
// Si viene imagen JPEG, la deja lista para multipart.
// Si viene 401/XML/HTML/error, NO traba el flujo:
// manda una marca de fallo para que el proceso avance igual.

function failPhoto(reason, details) {
    const cameraKey = msg.camera_key || "camara";
    const cameraLabel = msg.camera_label || cameraKey;

    node.warn(cameraLabel + " FOTO FALLIDA: " + reason);

    msg.payload = {
        ok: false,
        failed: true,
        reason,
        details: details || "",
        capture_id: msg.capture_id,
        camera_key: cameraKey,
        camera_label: cameraLabel
    };

    return msg;
}

let buf = msg.payload;

const cameraKey = msg.camera_key || "camara";
const cameraLabel = msg.camera_label || cameraKey;
const filename = cameraKey + ".jpg";

// Si el HTTP Request devolvió error propio
if (msg.error) {
    return failPhoto("HTTP_REQUEST_ERROR", String(msg.error.message || msg.error));
}

// Si no vino Buffer
if (!Buffer.isBuffer(buf)) {
    return failPhoto("PAYLOAD_NO_ES_BUFFER", typeof buf);
}

// Si vino vacío
if (!buf || buf.length === 0) {
    return failPhoto("RESPUESTA_VACIA", "");
}

// 1) Si ya viene JPEG directo, usarlo así nomás.
if (buf.length >= 3 && buf[0] === 0xFF && buf[1] === 0xD8 && buf[2] === 0xFF) {
    msg.payload = {
        ok: true,
        file: {
            value: buf,
            options: {
                filename,
                contentType: "image/jpeg"
            }
        },
        capture_id: msg.capture_id,
        camera_key: cameraKey,
        camera_label: cameraLabel
    };

    node.status({
        fill: "green",
        shape: "dot",
        text: cameraLabel + " OK"
    });

    return msg;
}

// 2) Si viene como texto, HTML, XML o multipart, inspeccionarlo.
let txt = buf.toString("latin1");
let head = txt.slice(0, 500);

// Detección clara de 401
if (
    head.indexOf("401") >= 0 ||
    head.toLowerCase().indexOf("unauthorized") >= 0 ||
    head.indexOf("<statusValue>401</statusValue>") >= 0
) {
    return failPhoto("401_UNAUTHORIZED", head.slice(0, 300));
}

// XML de error
if (
    head.indexOf("<?xml") >= 0 ||
    head.indexOf("<ResponseStatus") >= 0 ||
    head.indexOf("<userCheck") >= 0
) {
    return failPhoto("XML_ERROR_NO_IMAGEN", head.slice(0, 300));
}

// HTML de error
if (
    head.toLowerCase().indexOf("<!doctype html") >= 0 ||
    head.toLowerCase().indexOf("<html") >= 0
) {
    return failPhoto("HTML_ERROR_NO_IMAGEN", head.slice(0, 300));
}

// 3) Buscar inicio JPEG por firma binaria FF D8 FF.
let start = -1;

for (let n = 0; n < buf.length - 2; n++) {
    if (buf[n] === 0xFF && buf[n + 1] === 0xD8 && buf[n + 2] === 0xFF) {
        start = n;
        break;
    }
}

if (start < 0) {
    return failPhoto("NO_ENCONTRE_INICIO_JPEG", head.slice(0, 300));
}

// 4) Buscar fin JPEG por firma FF D9.
let end = -1;

for (let n = buf.length - 2; n >= start; n--) {
    if (buf[n] === 0xFF && buf[n + 1] === 0xD9) {
        end = n + 1;
        break;
    }
}

if (end < 0) {
    return failPhoto("NO_ENCONTRE_FIN_JPEG", head.slice(0, 300));
}

let jpg = buf.subarray(start, end + 1);

msg.payload = {
    ok: true,
    file: {
        value: jpg,
        options: {
            filename,
            contentType: "image/jpeg"
        }
    },
    capture_id: msg.capture_id,
    camera_key: cameraKey,
    camera_label: cameraLabel
};

node.status({
    fill: "green",
    shape: "dot",
    text: cameraLabel + " JPEG OK"
});

return msg;

// ======================================================
// CONFIG CENTRAL PRODUCCION
// ESTE ES EL UNICO LUGAR PARA CONFIGURAR LA ESTACION
// Y LA CANTIDAD DE CAMARAS.
// ======================================================

const accessControl = {
    key: "teclado",
    name: "Teclado Hikvision",
    ip: "192.168.1.25",
    capture: true,
    health: true,
    snapshot_path: "/ISAPI/Streaming/channels/1/picture",
    health_path: "/ISAPI/System/deviceInfo"
};

// Agregar o quitar cámaras solamente acá.
// La cantidad es dinámica.
const cameras = [
    {
        key: "camara_2",
        name: "Cámara 2",
        ip: "192.168.1.26",
        capture: true,
        health: true,
        snapshot_path: "/ISAPI/Streaming/channels/1/picture",
        health_path: "/ISAPI/System/status"
    },
    {
        key: "camara_3",
        name: "Cámara 3",
        ip: "192.168.1.27",
        capture: true,
        health: true,
        snapshot_path: "/ISAPI/Streaming/channels/1/picture",
        health_path: "/ISAPI/System/status"
    }
];

const cfg = {
    station_id: "2",
    test_mode: false, // Operación del cargadero: PLC, fotos y despachos activos.

    // Compatibilidad con los nodos de sincronización de usuarios.
    hik_ip: accessControl.ip,

    access_control: accessControl,
    cameras: cameras,

    backend_base: "https://cargaderomuni.onrender.com",

    // Usuarios activos
    beginTime: "2025-01-01T00:00:00",
    endTime: "2037-12-31T23:59:59",

    // Usuarios inactivos: quedan CADUCADOS, no eliminados.
    disabledBeginTime: "2000-01-01T00:00:00",
    disabledEndTime: "2000-01-02T00:00:00",

    // Hikvision puerta / plan
    doorNo: 1,
    doorRight: "1",
    planTemplateNo: "1",

    // HTTP
    timeoutMs: 10000,
    capture_timeout_ms: 5000
};

flow.set("hik_config", cfg);
msg.hik_config = cfg;

node.status({
    fill: "green",
    shape: "dot",
    text:
        "estación " + cfg.station_id +
        " | cámaras=" + cfg.cameras.length +
        " | teclado=" + (cfg.access_control.capture ? "foto" : "sin foto")
});

return msg;

