// Lee valor desde nodo S7 y lo escala.
// Este nodo acepta distintos formatos posibles:
// msg.payload = 12345
// msg.payload = "12345"
// msg.payload = [12345]
// msg.payload = { TANK: 12345 }
// msg.payload = { value: 12345 }

function extraerRaw(msg) {
    const p = msg.payload;

    if (typeof p === "number") return p;

    if (typeof p === "string" && p.trim() !== "") {
        return Number(p);
    }

    if (Array.isArray(p) && p.length > 0) {
        return Number(p[0]);
    }

    if (p && typeof p === "object") {
        if (p.TANK !== undefined) return Number(p.TANK);
        if (p.value !== undefined) return Number(p.value);
        if (p.data !== undefined && Array.isArray(p.data)) return Number(p.data[0]);
        if (p.payload !== undefined) return Number(p.payload);
    }

    return NaN;
}

const raw = extraerRaw(msg);

if (!Number.isFinite(raw)) {
    node.warn("No pude leer valor numérico desde S7. Payload recibido: " + JSON.stringify(msg.payload));
    return null;
}

// -----------------------------
// CONFIGURACIÓN DE ESCALA
// -----------------------------
// Si el canal analógico en TIA está configurado como 0-20 mA:
// 4 mA ≈ 5530 y 20 mA ≈ 27648.
//
// Si el canal en TIA está configurado directamente como 4-20 mA,
// probablemente 4 mA sea 0 y 20 mA sea 27648.
// En ese caso cambiá RAW_AT_4MA a 0.

const RAW_AT_4MA = 5530;
const RAW_AT_20MA = 27500;

// Escala eléctrica del sensor.
const MA_AT_0_PERCENT = 4;
const MA_AT_100_PERCENT = 20;

// -----------------------------
// CÁLCULO
// -----------------------------
let mA = MA_AT_0_PERCENT + ((raw - RAW_AT_4MA) * (MA_AT_100_PERCENT - MA_AT_0_PERCENT) / (RAW_AT_20MA - RAW_AT_4MA));

// Limitar por seguridad.
mA = Math.max(MA_AT_0_PERCENT, Math.min(MA_AT_100_PERCENT, mA));

let level_pct = ((mA - MA_AT_0_PERCENT) * 100) / (MA_AT_100_PERCENT - MA_AT_0_PERCENT);
level_pct = Math.max(0, Math.min(100, level_pct));

msg.payload = {
    raw: raw,
    mA: Number(mA.toFixed(3)),
    level_pct: Number(level_pct.toFixed(2))
};

node.status({
    fill: "green",
    shape: "dot",
    text: `raw ${raw} | ${msg.payload.mA} mA | ${msg.payload.level_pct}%`
});

return msg;

