// ======================================================
//   S7 -> BOMBA 1 -> RUN/STOP -> HEARTBEAT
//   Robusto para payload booleano, número, array u objeto
// ======================================================

const PUMP_ID = 34;
const PLC_IP = "192.168.1.32";
const SIGNAL_NAME = "BOMBA 1";

flow.set("health_plc_last_ok", Date.now());

// ------------------------------------------------------
// 1) Extraer valor crudo recibido desde el nodo S7
// ------------------------------------------------------
let raw = undefined;

// Caso 1: payload directo: true / false / 1 / 0
if (
    msg.payload === true ||
    msg.payload === false ||
    typeof msg.payload === "number" ||
    typeof msg.payload === "string"
) {
    raw = msg.payload;
}

// Caso 2: payload array: [true] / [1] / [0]
else if (Array.isArray(msg.payload)) {
    raw = msg.payload[0];
}

// Caso 3: payload.data array
else if (msg.payload && Array.isArray(msg.payload.data)) {
    raw = msg.payload.data[0];
}

// Caso 4: payload como objeto con nombre de variable
else if (msg.payload && Object.prototype.hasOwnProperty.call(msg.payload, SIGNAL_NAME)) {
    raw = msg.payload[SIGNAL_NAME];
}

// Caso 5: payload.value
else if (msg.payload && Object.prototype.hasOwnProperty.call(msg.payload, "value")) {
    raw = msg.payload.value;
}

// Caso 6: fallback completo
else {
    raw = msg.payload;
}

// ------------------------------------------------------
// 2) Normalizar valor a booleano
// ------------------------------------------------------
let activa = false;
let quality = "ok";

if (raw === true || raw === 1 || raw === "1" || raw === "true" || raw === "TRUE" || raw === "run" || raw === "RUN") {
    activa = true;
} else if (raw === false || raw === 0 || raw === "0" || raw === "false" || raw === "FALSE" || raw === "stop" || raw === "STOP") {
    activa = false;
} else {
    activa = false;
    quality = "bad_raw_value";
}

const state = activa ? "run" : "stop";

// ------------------------------------------------------
// 3) Armar heartbeat para backend
// ------------------------------------------------------
msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    pump_id: PUMP_ID,
    state: state,
    relay: activa,

    // diagnóstico
    raw: raw,
    signal: SIGNAL_NAME,
    plc_ip: PLC_IP,
    source: "iot2050-node-red-s7",
    quality: quality,

    // versión del flujo
    fw: "iot2050-s7-heartbeat-bomba1-v2.0",

    // timestamps
    ts_unix_ms: Date.now(),
    ts_iso: new Date().toISOString()
};

// Estado visual del nodo en Node-RED
node.status({
    fill: activa ? "green" : "grey",
    shape: "dot",
    text: `${SIGNAL_NAME}: ${state} | raw=${raw}`
});

return msg;

