return [hik, reports];

const backend = "https://cargaderomuni.onrender.com";
const code = Number(msg.statusCode || 0);
const elapsed = msg._health_started_at ? Math.max(0, Date.now() - msg._health_started_at) : null;

let status = "offline";
let error = null;

if (msg.error) {
  status = "offline";
  error = msg.error.message || String(msg.error);
} else if (code === 401 || code === 403) {
  status = "auth_error";
  error = "Equipo accesible pero rechazó las credenciales";
} else if (code >= 200 && code < 400) {
  status = "online";
} else {
  status = "offline";
  error = code ? ("HTTP " + code) : "Sin respuesta";
}

msg.method = "POST";
msg.url = backend + "/system-health/heartbeat";
msg.headers = {"Content-Type":"application/json"};
msg.payload = {
  device_id: msg.device_id,
  device_type: msg.device_type,
  name: msg.name,
  ip: msg.ip,
  station_id: msg.station_id || String((flow.get("hik_config") || {}).station_id || "2"),
  status,
  latency_ms: elapsed,
  error,
  metadata:{http_status:code}
};
